//! The Rust core must produce exactly what the original Python core did.
//! Fixture: tests/fixtures/parity.json, generated by tools/gen_parity.py.

use lyrictoolsnotepad::core::{self, RhymeKind, WordResult, datamuse};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/parity.json")).unwrap()
}

fn expected_results(v: &Value) -> Vec<WordResult> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|r| WordResult {
            word: r["word"].as_str().unwrap().to_string(),
            syllables: r["syllables"].as_u64().unwrap() as u32,
            score: r["score"].as_i64().unwrap(),
        })
        .collect()
}

fn fake_fetch(fx: &Value) -> impl Fn(&[(&str, String)]) -> Result<Vec<Value>, datamuse::DatamuseError> + '_ {
    move |params| {
        for (relation, rows) in fx["fake_datamuse"].as_object().unwrap() {
            if params.iter().any(|(k, _)| k == relation) {
                return Ok(rows.as_array().unwrap().clone());
            }
        }
        Ok(Vec::new())
    }
}

/// Compare and report the first few mismatches by name, not a 3000-line diff.
fn check<T: PartialEq + std::fmt::Debug>(what: &str, cases: Vec<(String, T, T)>) {
    let bad: Vec<_> = cases.iter().filter(|(_, got, want)| got != want).collect();
    for (key, got, want) in bad.iter().take(5) {
        eprintln!("{what} mismatch for {key:?}:\n  got  {got:?}\n  want {want:?}");
    }
    assert!(bad.is_empty(), "{} of {} {what} cases differ", bad.len(), cases.len());
}

#[test]
fn syllables_match_python() {
    let fx = fixture();
    let cases = fx["syllables"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(w, n)| (w.clone(), core::syllables_for_word(w), n.as_u64().unwrap() as u32))
        .collect();
    check("syllables_for_word", cases);
}

#[test]
fn lines_headers_tokens_match_python() {
    let fx = fixture();
    let obj = |k: &str| fx[k].as_object().unwrap().clone();
    check(
        "syllables_for_line",
        obj("lines")
            .iter()
            .map(|(l, n)| (l.clone(), core::syllables_for_line(l), n.as_u64().unwrap() as u32))
            .collect(),
    );
    check(
        "is_section_header",
        obj("headers").iter().map(|(l, b)| (l.clone(), core::is_section_header(l), b.as_bool().unwrap())).collect(),
    );
    check(
        "tokenize_line",
        obj("tokens")
            .iter()
            .map(|(l, t)| {
                let want: Vec<String> = t.as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_string()).collect();
                let got: Vec<String> = core::tokenize_line(l).into_iter().map(String::from).collect();
                (l.clone(), got, want)
            })
            .collect(),
    );
}

#[test]
fn offline_rhymes_match_python() {
    let fx = fixture();
    for (key, kind) in [("perfect", RhymeKind::Perfect), ("near", RhymeKind::Near)] {
        let cases = fx[key]
            .as_object()
            .unwrap()
            .iter()
            .map(|(a, want)| (a.clone(), core::find_words_local(a, kind, 80), expected_results(want)))
            .collect();
        check(key, cases);
    }
}

#[test]
fn deep_search_matches_python() {
    let fx = fixture();
    let fetch = fake_fetch(&fx);
    let cases = fx["deep"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(a, want)| (a.clone(), datamuse::find_words_deep_with(a, 150, &fetch), expected_results(want)))
        .collect();
    check("deep", cases);
}

#[test]
fn synonyms_match_python() {
    let fx = fixture();
    let fetch = fake_fetch(&fx);
    let cases = fx["synonyms"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(a, want)| (a.clone(), datamuse::find_synonyms_with(a, 60, &fetch).unwrap(), expected_results(want)))
        .collect();
    check("synonyms", cases);
}

#[test]
fn deep_search_survives_network_failure() {
    let fail = |_: &[(&str, String)]| Err(datamuse::DatamuseError("no connection".into()));
    assert!(!datamuse::find_words_deep_with("night", 20, &fail).is_empty());
}
